export default async function PortalLayout({ children }) {
  const nutzer = await portalNutzer();
  const b = backend();
  const admin = nutzer.rollen?.includes("admin");
  // Zähler sind nicht kritisch – Fehler dürfen das Portal nicht blockieren
  const [threads, hinweise, aufgaben] = await Promise.all([
    b.nachrichtenThreads(nutzer).catch(() => []),
    b.benachrichtigungen(nutzer, { limit: 8 }).catch(() => ({ eintraege: [], ungelesen: 0 })),
    admin ? b.aufgaben(nutzer, { zustaendigId: nutzer.id, status: "offen" }).catch(() => []) : [],
  ]);
  const ungelesen = threads.reduce((s, t) => s + (t.ungelesen || 0), 0);
  const aufgabenFaellig = aufgaben.filter((a) => a.ueberfaellig || a.heuteFaellig).length;
  return (
    <PortalRahmen
      nutzer={nutzerFuerBrowser(nutzer)}
      ungelesen={ungelesen}
      hinweise={{ eintraege: hinweise.eintraege, ungelesen: hinweise.ungelesen }}
      aufgabenFaellig={aufgabenFaellig}
      demo={istDemo()}
    >
      {children}
    </PortalRahmen>
  );
}
// GET  /api/admin/aufgaben?ansicht=meine|offen|alle|ueberfaellig|erledigt&bezug=art:id – Aufgaben & Wiedervorlagen (nur admin)
// POST /api/admin/aufgaben – { titel, beschreibung?, faelligAm: "JJJJ-MM-TT", zustaendigId?, bezugArt?, bezugId? }
import { route } from "@/lib/plattform/server/route";

function aufgabenFilter(ansicht, nutzer, bezug = "") {
  const [bezugArt, bezugId] = String(bezug || "").split(":");
  return {
    ...(ansicht === "meine" ? { zustaendigId: nutzer.id, status: "offen" } : {}),
    ...(ansicht === "offen" ? { status: "offen" } : {}),
    ...(ansicht === "ueberfaellig" ? { nurUeberfaellig: true } : {}),
    ...(ansicht === "erledigt" ? { status: "erledigt" } : {}),
    ...(bezugArt && bezugId ? { bezugArt, bezugId } : {}),
  };
}

export const GET = route({ admin: true }, async ({ backend, nutzer, suche }) => ({
  ok: true,
  aufgaben: await backend.aufgaben(nutzer, aufgabenFilter(suche.get("ansicht") || "alle", nutzer, suche.get("bezug"))),
}));

