  if (teil === "vorlagen" && teile[3] === "vorschau") anf[0].stufe = 1;
  return anf;
}

/** Fehlende Rechte (leer = erlaubt) */
export function fehlendeRechte(n, anforderungen) {
  return anforderungen.filter((a) => stufe(n, a.bereich) < a.stufe);
}

