// src/components/Portal/felder.js
//
// Formularbausteine für Portal, Login und Registrierung (ohne Hooks).

import { cn } from "@/components/ui/cn";

export const eingabe =
  "block h-12 w-full min-w-0 rounded-xl bg-white px-4 text-[15px] text-ink-900 outline-none ring-1 ring-inset ring-ink-200 transition-shadow placeholder:text-ink-400 hover:ring-ink-300 focus-visible:ring-2 focus-visible:ring-ov-500 disabled:bg-ink-50 disabled:text-ink-500";
export const textbereich = cn(eingabe, "h-auto min-h-[112px] py-3 leading-relaxed");
export const auswahlfeld = cn(eingabe, "appearance-none bg-[url('data:image/svg+xml,%3Csvg%20xmlns=%22http://www.w3.org/2000/svg%22%20viewBox=%220%200%2020%2020%22%20fill=%22%236b7486%22%3E%3Cpath%20d=%22M5.3%207.3a1%201%200%200%201%201.4%200L10%2010.6l3.3-3.3a1%201%200%201%201%201.4%201.4l-4%204a1%201%200%200%201-1.4%200l-4-4a1%201%200%200%201%200-1.4z%22/%3E%3C/svg%3E')] bg-[length:18px] bg-[right_14px_center] bg-no-repeat pr-10");
export const labelKlasse = "mb-1.5 block text-[13.5px] font-semibold text-ink-700";

export function Feld({ id, label, hinweis, fehler, pflicht, children, className }) {
  return (
    <div className={cn("min-w-0", className)}>
      {label && (
        <label htmlFor={id} className={labelKlasse}>
          {label}
          {pflicht && <span aria-hidden="true"> *</span>}
        </label>
      )}
      {children}
      {hinweis && !fehler && <p id={id ? `${id}-hinweis` : undefined} className="mt-1.5 text-[12.5px] leading-snug text-ink-500">{hinweis}</p>}
      {fehler && <p className="mt-1.5 text-[12.5px] font-medium text-red-700">{fehler}</p>}
    </div>
  );
}

/** Auswahl-Chip (Checkbox/Radio im Kartenstil) */
export function Chip({ name, value, checked, onChange, type = "checkbox", children }) {
  return (
    <label
      className={cn(
        "inline-flex cursor-pointer select-none items-center gap-2 rounded-full px-3.5 py-2 text-[13.5px] font-medium ring-1 ring-inset transition-colors has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ov-500",
        checked ? "bg-ov-600 text-white ring-ov-600" : "bg-white text-ink-700 ring-ink-200 hover:ring-ink-300"
      )}
    >
      <input type={type} name={name} value={value} checked={checked} onChange={onChange} className="sr-only" />
      {children}
    </label>
  );
}

export function FehlerBox({ children }) {
  if (!children) return null;
  return (
    <p role="alert" className="rounded-xl bg-red-50 px-4 py-3 text-[14px] text-red-800 ring-1 ring-red-200">
      {children}
    </p>
  );
}

export function ErfolgBox({ children }) {
  if (!children) return null;
  return (
    <p role="status" className="rounded-xl bg-ov-50 px-4 py-3 text-[14px] text-ov-900 ring-1 ring-ov-200">
      {children}
    </p>
  );
}
}

/** Überschrift eines Eingabeblocks */
export function Gruppe({ titel, children, className }) {
  return (
    <div className={cn("space-y-5", className)}>
      {titel && <p className="text-[11.5px] font-semibold uppercase tracking-[0.16em] text-ink-500">{titel}</p>}
      {children}
    </div>
  );
}

/** Beobachtet die Breite eines Elements (für Diagramme ohne Skalierung der Schrift). */
export function useBreite(standard = 720) {
  const ref = useRef(null);
  const [breite, setBreite] = useState(standard);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const ro = new ResizeObserver(([e]) => {
      const w = Math.round(e.contentRect.width);
      if (w > 0) setBreite(w);
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return [ref, breite];
}

/** Kennzahl-Kachel */
export function Kennzahl({ label, children, zusatz, icon: Icon, ton = "hell", className }) {
  const toene = {
    hell: "bg-white ring-1 ring-ink-200/70 text-ink-900",
    gruen: "bg-ov-600 text-white",
    navy: "bg-navy-950 text-white",
    sand: "bg-sand-50 ring-1 ring-ink-200/60 text-ink-900",
  };
  const dunkel = ton === "gruen" || ton === "navy";
  return (
    <div className={cn("relative overflow-hidden rounded-2xl p-4 md:p-5", toene[ton], className)}>
      <p className={cn("flex items-center gap-1.5 text-[12.5px] font-medium", ton === "gruen" ? "text-white" : dunkel ? "text-white/75" : "text-ink-500")}>
      <ArrowRight aria-hidden="true" className="h-4 w-4 transition-transform group-hover:translate-x-0.5" />
    </Link>
  );
}

/** Tabelle mit horizontalem Scroll auf kleinen Bildschirmen */
export function Tabelle({ kopf = [], children, className }) {
  return (
    <div className={cn("-mx-5 overflow-x-auto md:-mx-6", className)}>
      <table className="w-full min-w-[640px] text-left text-[14px]">
        <thead>
          <tr className="border-b border-ink-100 text-[12px] font-semibold uppercase tracking-wider text-ink-500">
            {kopf.map((k, i) => (
              <th key={i} scope="col" className="px-5 py-3 font-semibold first:pl-5 md:px-6">
                {k}
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="divide-y divide-ink-100">{children}</tbody>
      </table>
    </div>
  );
}

export const zelle = "px-5 py-3.5 align-top md:px-6";

/** Hinweisbox */
export function Hinweis({ ton = "info", titel, children, className, icon: Icon }) {
  const t = {
    info: "bg-navy-50 text-navy-900 ring-navy-100",
    ok: "bg-ov-50 text-ov-900 ring-ov-200",
    warn: "bg-sun-300/20 text-ink-900 ring-sun-400/40",
    neutral: "bg-ink-50 text-ink-800 ring-ink-200",
  }[ton];
  return (
    <div className={cn("flex gap-3 rounded-2xl px-4 py-3.5 text-[14px] leading-relaxed ring-1 ring-inset", t, className)}>
      {Icon && <Icon aria-hidden="true" className="mt-0.5 h-[18px] w-[18px] shrink-0" />}
      <div className="min-w-0">
        {titel && <p className="font-semibold">{titel}</p>}
        <div className={titel ? "mt-0.5" : ""}>{children}</div>
      </div>
    </div>
  );
}

/** Fortschrittsbalken „Datenraum-Qualität“ (auch in Karten nutzbar) */
export function QualitaetsBalken({ quote, label = "Datenraum-Qualität", klein = false }) {
  const q = Math.max(0, Math.min(100, Number(quote) || 0));
  return (
    <div className="min-w-0">
      <div className={cn("flex items-baseline justify-between gap-2", klein ? "text-[12px]" : "text-[13px]")}>
        <span className="text-ink-600">{label}</span>
        <span className="ov-num font-bold text-ink-900">{q} %</span>
      </div>
