        </Feld>
        <Feld id={`${id}-fu`} label="Funktion"><input id={`${id}-fu`} className={eingabe} value={d.funktion} onChange={f("funktion")} maxLength={80} placeholder="z. B. Bürgermeisterin" /></Feld>
