                  {Object.entries(BEDINGUNG_FELDER).map(([k, x]) => <option key={k} value={k}>{x.label}</option>)}
                </select>
                <select aria-label="Vergleich" className={klein} value={b.op} onChange={(e) => setB(i, { op: e.target.value, wert: e.target.value === "in" ? [] : "" })}>
