    const start = el?.selectionStart ?? wert.length;
    const ende = el?.selectionEnd ?? wert.length;
    const neu = wert.slice(0, start) + t + wert.slice(ende);
    setD({ ...d, [feld]: neu });
    requestAnimationFrame(() => {
      if (!el) return;
      el.focus();
      el.setSelectionRange(start + t.length, start + t.length);
