	kandidaten = [u for u in p["uebergaenge"] if u["nach"] == nach and von in u["von"]]
	if not kandidaten:
		frappe.throw(
			f"Wechsel von „{status_label(art, von)}“ nach „{status_label(art, nach)}“ ist nicht vorgesehen.",
			frappe.DuplicateEntryError,
