	konten = []
	for kid in frappe.get_all("Plattform Konto Rolle", filters={"rolle": "admin", "parenttype": "Plattform Konto"}, pluck="parent"):
		k = frappe.db.get_value("Plattform Konto", kid, ["name", "email", "aktiv", "backoffice_rollen"], as_dict=True)
