import { chromium } from "playwright";
const B = "http://localhost:3100";
const r0 = await fetch(B + "/api/auth/login", { method: "POST", headers: { Origin: B, "Content-Type": "application/json" }, body: JSON.stringify({ email: "admin@example.com", passwort: "Demo-2026!" }) });
const cookies = r0.headers.getSetCookie().map((c) => { const [p] = c.split(";"); const i = p.indexOf("="); return { name: p.slice(0, i), value: p.slice(i + 1), domain: "localhost", path: "/" }; }).filter((c) => c.value);
const b = await chromium.launch();
try {
  const ctx = await b.newContext({ viewport: { width: 390, height: 844 } });
  await ctx.addCookies(cookies);
  const p = await ctx.newPage();
  await p.goto(B + process.argv[2], { waitUntil: "load", timeout: 180000 });
  await p.waitForTimeout(2000);
  console.log(await p.evaluate(() => [...document.querySelectorAll("body *")].filter((e) => e.getBoundingClientRect().right > 392).slice(0, 8).map((e) => `${e.tagName}.${String(e.className).slice(0, 80)} r=${Math.round(e.getBoundingClientRect().right)}`).join("\n")));
} finally { await b.close(); }
EOF
